// Archivo: app/api/salud/route.ts
// Comprueba si Vercel esta viendo tus variables de entorno.
// BORRA este archivo cuando termines de depurar.

import { NextResponse } from "next/server";

export const dynamic = "force-dynamic";

// ─── CAMBIA ESTA LISTA POR TUS VARIABLES ───
const OBLIGATORIAS = [
  "NEXT_PUBLIC_SUPABASE_URL",
  "NEXT_PUBLIC_SUPABASE_ANON_KEY",
  "SUPABASE_SERVICE_ROLE_KEY",
  "OPENAI_API_KEY",
];

export async function GET() {
  const revision = OBLIGATORIAS.map((nombre) => {
    const valor = process.env[nombre];
    const limpio = valor ? valor.trim() : "";
    return {
      nombre,
      presente: limpio.length > 0,
      letras: limpio.length,
      empiezaPor: limpio ? limpio.slice(0, 4) + "..." : null,
      // Aviso tipico: pegaste la clave con comillas o con un espacio
      sospechosa: Boolean(valor && valor !== limpio) || limpio.startsWith("\""),
    };
  });

  const faltan = revision.filter((v) => !v.presente).map((v) => v.nombre);

  return NextResponse.json({
    entorno: process.env.VERCEL_ENV || "development (tu ordenador)",
    rama: process.env.VERCEL_GIT_COMMIT_REF || "sin rama",
    todoCorrecto: faltan.length === 0,
    faltan,
    revision,
  });
}
